package project.init.account.config.database;import com.zaxxer.hikari.HikariDataSource;import org.springframework.orm.jpa.JpaTransactionManager;import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;import project.init.account.domain.properties.DatabaseProperties;import javax.sql.DataSource;import java.util.HashMap;public class Factory {    public static DataSource createDataSource(DatabaseProperties p) {        HikariDataSource dataSource = new HikariDataSource();        dataSource.setDriverClassName(p.getDriverClassName());        dataSource.setJdbcUrl(p.getUrl());        dataSource.setUsername(p.getUsername());        dataSource.setPassword(p.getPassword());        dataSource.setSchema(p.getSchema());        dataSource.setPoolName(p.getDriverClassName());        dataSource.setMinimumIdle(p.getHikari().getMinimumIdle());        dataSource.setMaximumPoolSize(p.getHikari().getMaximumPoolSize());        dataSource.setConnectionTimeout(p.getHikari().getConnectionTimeout());        dataSource.setIdleTimeout(p.getHikari().getIdleTimeout());        dataSource.setMaxLifetime(p.getHikari().getMaxLifetime());        dataSource.setAutoCommit(p.getHikari().isAutoCommit());        return dataSource;    }    public static LocalContainerEntityManagerFactoryBean createEntityManager(DataSource dataSource, String... packagesToScan) {        LocalContainerEntityManagerFactoryBean em = new LocalContainerEntityManagerFactoryBean();        em.setDataSource(dataSource);        em.setPackagesToScan(packagesToScan);        HibernateJpaVendorAdapter vendorAdapter = new HibernateJpaVendorAdapter();        em.setJpaVendorAdapter(vendorAdapter);        HashMap<String, Object> properties = new HashMap<>();        em.setJpaPropertyMap(properties);        return em;    }    public static JpaTransactionManager createTransactionManager(LocalContainerEntityManagerFactoryBean entityManagerFactory) {        JpaTransactionManager transactionManager = new JpaTransactionManager();        transactionManager.setEntityManagerFactory(entityManagerFactory.getObject());        return transactionManager;    }}